def _validate_grade_compare_result(
    result: Any, *, where: str = "result"
) -> tuple[list[str], list[dict], list[str], list[dict]]:
    """Validate a complete :func:`grade_compare` result.

    Returns fresh ``names``, ``pairs`` and ``scenarios`` axes plus the
    data rows in scenario order, checking the
    ``climate-grid/rwc2-v1`` contract: key order, the axes and the
    per-scenario rows with key order
    ``scenario, valid, missing, mean, std, band``.  ``mean``, ``std``
    and ``band`` are ``None`` together or present together as two-item
    columns; ``missing`` must equal the number of names minus
    ``valid``.
    """
    if not isinstance(result, dict):
        raise TypeError(f"{where} must be a dict")
    if tuple(result.keys()) != _GRADE_COMPARE_OUTPUT_KEYS:
        raise ValueError(
            f"{where} must have exactly the keys schema, names, pairs, "
            "scenarios, data in order"
        )

    schema = result["schema"]
    if not isinstance(schema, str):
        raise TypeError(f"{where}.schema must be a str")
    if schema != _GRADE_COMPARE_SCHEMA:
        raise ValueError(
            f"{where}.schema must be {_GRADE_COMPARE_SCHEMA!r}"
        )

    raw_names = result["names"]
    if not isinstance(raw_names, list):
        raise TypeError(f"{where}.names must be a list")
    if not raw_names:
        raise ValueError(f"{where}.names must be non-empty")
    names: list[str] = []
    seen_names: set[str] = set()
    for index, name in enumerate(raw_names):
        name_where = f"{where}.names[{index}]"
        if not isinstance(name, str):
            raise TypeError(f"{name_where} must be a str")
        if name == "":
            raise ValueError(f"{name_where} must be non-empty")
        if name in seen_names:
            raise ValueError(f"duplicate {where} name: {name!r}")
        seen_names.add(name)
        names.append(name)

    raw_pairs = result["pairs"]
    if not isinstance(raw_pairs, list):
        raise TypeError(f"{where}.pairs must be a list")
    if not raw_pairs:
        raise ValueError(f"{where}.pairs must be non-empty")
    pairs: list[dict] = []
    for index, pair in enumerate(raw_pairs):
        pair_where = f"{where}.pairs[{index}]"
        if not isinstance(pair, dict):
            raise TypeError(f"{pair_where} must be a dict")
        if tuple(pair.keys()) != _GRADE_WINDOW_CHANGE_PAIR_KEYS:
            raise ValueError(
                f"{pair_where} must have exactly the keys left, right "
                "in order"
            )
        left = pair["left"]
        right = pair["right"]
        if not isinstance(left, str):
            raise TypeError(f"{pair_where}.left must be a str")
        if not isinstance(right, str):
            raise TypeError(f"{pair_where}.right must be a str")
        if left == "":
            raise ValueError(f"{pair_where}.left must be non-empty")
        if right == "":
            raise ValueError(f"{pair_where}.right must be non-empty")
        pairs.append({"left": left, "right": right})

    raw_scenarios = result["scenarios"]
    if not isinstance(raw_scenarios, list):
        raise TypeError(f"{where}.scenarios must be a list")
    if not raw_scenarios:
        raise ValueError(f"{where}.scenarios must be non-empty")
    scenarios: list[str] = []
    seen_scenarios: set[str] = set()
    for index, scenario in enumerate(raw_scenarios):
        scenario_where = f"{where}.scenarios[{index}]"
        if not isinstance(scenario, str):
            raise TypeError(f"{scenario_where} must be a str")
        if scenario == "":
            raise ValueError(f"{scenario_where} must be non-empty")
        if scenario in seen_scenarios:
            raise ValueError(
                f"duplicate {where} scenario: {scenario!r}"
            )
        seen_scenarios.add(scenario)
        scenarios.append(scenario)

    data = result["data"]
    if not isinstance(data, list):
        raise TypeError(f"{where}.data must be a list")
    if len(data) != len(scenarios):
        raise ValueError(
            f"{where}.data must contain exactly one row per scenario"
        )

    n_names = len(names)
    out_rows: list[dict] = []
    for row_index, row in enumerate(data):
        row_where = f"{where}.data[{row_index}]"
        if not isinstance(row, dict):
            raise TypeError(f"{row_where} must be a dict")
        if tuple(row.keys()) != _GRADE_COMPARE_ROW_KEYS:
            raise ValueError(
                f"{row_where} must have exactly the keys scenario, valid, "
                "missing, mean, std, band in order"
            )

        scenario_name = row["scenario"]
        if not isinstance(scenario_name, str):
            raise TypeError(f"{row_where}.scenario must be a str")
        expected_scenario = scenarios[row_index]
        if scenario_name != expected_scenario:
            raise ValueError(
                f"{row_where}.scenario {scenario_name!r} must follow "
                f"scenario order (expected {expected_scenario!r})"
            )

        valid = row["valid"]
        missing = row["missing"]
        if not isinstance(valid, int) or isinstance(valid, bool):
            raise TypeError(f"{row_where}.valid must be a non-bool int")
        if valid < 0 or valid > n_names:
            raise ValueError(
                f"{row_where}.valid must be between 0 and the number of "
                "names"
            )
        if not isinstance(missing, int) or isinstance(missing, bool):
            raise TypeError(f"{row_where}.missing must be a non-bool int")
        if missing != n_names - valid:
            raise ValueError(
                f"{row_where}.missing must equal the number of names "
                "minus valid"
            )

        mean = row["mean"]
        std = row["std"]
        band = row["band"]
        if mean is None or std is None or band is None:
            if mean is not None or std is not None or band is not None:
                raise ValueError(
                    f"{row_where}.mean, {row_where}.std and "
                    f"{row_where}.band must be None together"
                )
            out_rows.append(row)
            continue

        if not isinstance(mean, list):
            raise TypeError(f"{row_where}.mean must be a list")
        if len(mean) != 2:
            raise ValueError(f"{row_where}.mean must contain exactly 2 items")
        if not isinstance(std, list):
            raise TypeError(f"{row_where}.std must be a list")
        if len(std) != 2:
            raise ValueError(f"{row_where}.std must contain exactly 2 items")
        if not isinstance(band, list):
            raise TypeError(f"{row_where}.band must be a list")
        if len(band) != 2:
            raise ValueError(f"{row_where}.band must contain exactly 2 items")

        for column_index in range(2):
            _validate_number(
                mean[column_index],
                f"{row_where}.mean[{column_index}]",
                nullable=False,
            )
            _validate_number(
                std[column_index],
                f"{row_where}.std[{column_index}]",
                nullable=False,
            )
            if std[column_index] < 0:
                raise ValueError(
                    f"{row_where}.std[{column_index}] must be non-negative"
                )
            bounds = band[column_index]
            bounds_where = f"{row_where}.band[{column_index}]"
            if not isinstance(bounds, list):
                raise TypeError(f"{bounds_where} must be a list")
            if len(bounds) != 2:
                raise ValueError(
                    f"{bounds_where} must contain exactly 2 items"
                )
            _validate_number(
                bounds[0], f"{bounds_where}[0]", nullable=False
            )
            _validate_number(
                bounds[1], f"{bounds_where}[1]", nullable=False
            )
            if bounds[0] > bounds[1]:
                raise ValueError(
                    f"{bounds_where} lower bound must not exceed the "
                    "upper bound"
                )

        out_rows.append(row)

    return names, pairs, scenarios, out_rows


